Let $Q$ be a probability distribution over $\mathcal{X}\times[0,1]^{K}$ that generates a sequence of independent random vectors $(X^{Q},Y^{Q,(1)},\cdots,Y^{Q,(K)})$.
At each time point $t$, based on the covariate $X_{t}^{Q}\in\mathcal{X}$ drawn from the marginal distribution $Q_{X}$, a decision-maker selects an arm $k\in[K]$ and receives a random reward $Y_{t}^{Q,(k)}\in[0,1]$ associated with the chosen arm according to the conditional distribution $Q_{Y^{(k)}| X_{t}^{Q}}$. We assume that for any $k\in[K]$ and $t\geq1$, the random reward $Y_{t}^{Q,(k)}$ is a random variable with conditional expectation given by
\begin{align*}
\mathbb{E}\big[Y_{t}^{Q,(k)}\,|\,X_{t}^{Q}\big]=f_{k}^{Q}(X_{t}^{Q}),
\end{align*}
where $f_{k}^{Q}:\mathcal{X}\rightarrow[0,1]$ is an unknown function called a reward function. A policy $\pi$ is a collection of functions $\{\pi_{t}\}_{t\geq1}$ where $\pi_{t}: \mathcal{X}\rightarrow[K]$ prescribe the arm to pull at time $t$.

In the context of transfer learning, we assume that the decision-maker is given a batch dataset $\mathcal{D}^{P} \coloneqq \{(X_{i}^{P},\pi_{i}^{P}, Y_{i}^{P,(\pi_{i}^{P})})\}_{i=1}^{n_{P}}$. This dataset is collected from a contextual $K$-armed bandit over $n_{P}$ rounds, of which the underlying probability distribution $P$ generates a sequence of independent random vectors $(X^{P},Y^{P,(1)},\cdots,Y^{P,(K)})\in\mathcal{X}\times[0,1]^{K}$.
Here, $X_{i}^{P}\in\mathcal{X}$ represents the covariate observed at time $i$, policy $\pi_{i}^{P}:\mathcal{X}\rightarrow[K]$ denotes the selected arm at time $i$, and $Y_{i}^{P,(\pi_{i}^{P})}$ corresponds to the observed random reward at time $i$. Similar to the $Q$-bandit, it is assumed that for any $k\in[K]$ and $i\geq1$, the random reward $Y_{i}^{P,(k)}$ of the $P$-bandit obeys
\begin{align*}
\mathbb{E}\big[Y_{i}^{P,(k)}\,|\,X_{i}^{P}\big]=f_{k}^{P}(X_{i}^{P}),
\end{align*}
for an unknown function $f_{k}^{P}:\mathcal{X}\rightarrow[0,1]$. Throughout the paper, we denote $n \coloneqq n_{Q} \vee n_{P}$.

Recall that $\pi^{\star}$ is the oracle policy with access to full knowledge of the reward functions $\{f_{k}\}_{k=1}^{K}$.
It is straightforward to see that given a covariate value $x$, the oracle policy $\pi^{\star}$ selects any arm with the largest expected reward, with ties broken arbitrarily. In other words,
\begin{align*}
\pi^{\star}(x)\in\argmax_{k\in[K]}f_{k}(x).
\end{align*}
Therefore, for any policy $\pi=\{\pi_{t}\}_{t\geq1}$, the regret of $\pi$ in the $Q$-bandit defined in (\ref{eq:regret}) has the following expression:
\begin{align}
\mathbb{E}[R_{n_Q}(\pi)] & =\mathbb{E}\bigg[ \sum_{t=1}^{n_{Q}} \Big( f_{\pi^{\star}(X_t^Q)}(X_{t}^{Q})-f_{\pi_{t}(X_t^Q)}(X_{t}^{Q}) \Big) \bigg] \nonumber \\
& =\mathbb{E}\bigg[ \sum_{t=1}^{n_{Q}} \Big( \max_{k\in[K]} f_{k}(X_{t}^{Q})-f_{\pi_{t}(X_t^Q)}(X_{t}^{Q}) \Big)\bigg]. \label{eq:def-regret}
\end{align}
In the remainder of the paper, we may drop the subscript $n_Q$ whenever there is no confusion.

The reward functions $\{f_{k}\}_{k=1}^{K}$ are $\left(\beta,C_{\beta}\right)$-H\"{o}lder continuous for some constants $0<\beta\leq1,C_{\beta}>0$, i.e. for any $k\in[K]$,
\begin{align*}
\big|f_{k}(x)-f_{k}(x')\big|\leq C_{\beta} \| x-x'\|_{\infty}^{\beta},\quad\forall x,x'\in\mathcal{X}.
\end{align*}

Next, it is natural to expect that the gap between the reward functions is a pivotal measure of a contextual multi-armed bandit problem's complexity. To this end, let $f_{(1)}$ (resp.~$f_{(2)}$) denote the pointwise maximum (resp.~the second pointwise maximum) of the reward functions $\{f_{k}\}_{k=1}^{K}$, namely
\begin{align*}
f_{(1)}(x) & \coloneqq\max_{k\in[K]}f_{k}(x),
\end{align*}
and
\begin{align*}
f_{(2)}(x)\coloneqq\begin{cases}
\max\limits_{k\in[K]}\big\{ f_{k}(x):f_{k}(x)<f_{(1)}(x)\big\}, & \text{if }\min\limits_{k\in[K]}f_{k}(x)\neq\max\limits_{k\in[K]}f_{k}(x),\\
f_{(1)}(x), & \text{otherwise.}
\end{cases}
\end{align*}

There exist constants $\alpha\geq0,C_{\alpha}>0$ such that the reward functions $\{f_{k}\}_{k=1}^{K}$ and marginal distribution $Q_{X}$ satisfy
	\begin{align*}
		Q_X\big(0<f_{(1)}(X)-f_{(2)}(X)\leq\delta\big)\leq C_{\alpha}\delta^{\alpha},\quad\forall0<\delta\leq1.
	\end{align*}

Define the transfer exponent $\gamma \in \mathbb{R}_{+} \cup \{0,\infty\}$ of $P_{X}$ with respect to $Q_{X}$ to be the smallest constant such that
\begin{align}

P_{X}(B(x, r)) \geq c_{\gamma}r^{\gamma} Q_{X}(B(x, r)),\quad\forall x\in\mathsf{supp}(Q_{X}), r \in (0, 1],
\end{align}
for some constant $0 < c_{\gamma} \leq 1$.

Define the exploration coefficient $ \kappa  \in [0, 1]$ of a collection of distributions over the arm set $\{\mu(\cdot \, | \, x) \}_{x\in\mathcal{X}}$ with respect to $Q_X$ as
	\begin{align} 

	 \kappa  \defn \inf_{\substack{k\in [K],\,x\in \mathsf{supp}(Q_{X})}} K \mu(k \, | \, x).
\end{align}

Here, for any non-negative integer $l \geq 0$, we define a collection of bins $\mathcal{B}_{l}\defn \{B_{\mathsf k}\}_{\mathsf{k} \in [2^l]^d}$ where
\begin{align}
    B_{\mathsf{k}}\defn\{x\in\mathcal{X}:(k_{i}-1)2^{-l}\leq x_{i}\leq k_{i}2^{-l},\,k_{i}\in[2^{l}],\,i\in[d]\},\quad\forall\mathsf{k}=(k_{1},\dots,k_{d}).\label{def:bin}
\end{align}
Throughout the paper, we use $|B|$ to denote the side length of any bin $B$, i.e.~$|B|=2^{-l}$ for any $B\in\mathcal{B}_{l}$.

Next, given a subset $\mathcal{D}$ of the source dataset $\mathcal{D}^{P}$, for any bin $B$ and arm $k$, let $n_{k}^{P}(B;\mathcal{D})$ denote the number of samples in dataset $\mathcal{D}$ such that the covariate falls in bin $B$ and arm $k$ is pulled, i.e.
\begin{align}
    \label{eq:n-k-B-Pdata}
    n_{k}^{P}(B;\mathcal{D}) & \defn\sum_{(X_{i},\pi_{i},Y_{i})\in\mathcal{D}}\mathds{1}\{X_{i}\in B,\,\pi_{i}=k\}.
\end{align}

Let $\overline{Y}_{k}^{P}(B;\mathcal{D})$  denote the empirical mean of the reward of arm $k$ over bin $B$ in dataset~$\mathcal{D}$, namely
\begin{align}
\label{eq:Y-bar-k-B-Pdata}
\overline{Y}_{k}^{P}(B;\mathcal{D})\defn
\begin{cases}
    \frac{1}{n_{k}^{P}(B;\mathcal{D})}\sum\limits_{(X_{i},\pi_{i},Y_{i})\in\mathcal{D}}Y \mathds{1}\{X_{i}\in B,\,\pi_{i}=k\}, & \text{if }  n_{k}^{P}(B;\mathcal{D}) \neq 0, \\
    0, & \text{otherwise.}
\end{cases}
\end{align}

In addition, for any non-negative integer $\tau \geq 0$, bin $B$ and arm $k$, let us define
\begin{align}
U_{k}(\tau,B;\mathcal{D})\coloneqq
\begin{cases}
2\sqrt{\frac{2}{\tau+n_{k}^{P}(B;\mathcal{D})}\log^{+}(\frac{n_{Q}|B|^{d}}{\tau})} \vee 2C_{\beta}|B|^{\beta}, & \text{if } \tau > 0, \\
2\sqrt{\frac{2}{n_{k}^{P}(B;\mathcal{D})}\log^{+}(n_{Q}|B|^{d+2\beta}\vee\kappa n_{P}|B|^{d+2\beta+\gamma})} \vee 2C_{\beta}|B|^{\beta}, & \text{if } \tau = 0,
\end{cases} \label{eq:UCB}
\end{align}
where we recall the notation $\log^{+}(x)\defn\log(x)\vee1$ and use the convention $1/0 = \infty$. The $U_{k}(\tau,B;\mathcal{D})$ can be essentially viewed as a confidence bound that quantifies the uncertainty of the reward function estimator used in Algorithm~\ref{alg:UCB-TL}.

In order to achieve such an adaptive partition, for each bin $B$ and arm $k$, we assign a non-negative upper bound on the number of pulls, given by
\begin{align}
\tau^\star_k(B;\mathcal{D}) \defn \min_{\tau \in \{0\}\cup\mathbb{N}}\big\{ \tau : U_{k}(\tau,B;\mathcal{D}) 

\leq 2C_{\beta}|B|^{\beta}\big\}, \label{eq:tau-star}
\end{align}
where we recall the definition of $U_{k}(\tau,B;\mathcal{D})$ in \eqref{eq:UCB}.

\caption{Successive elimination procedure for a static bandit with source data}

\begin{algorithmic}[1]
\State{\textbf{Input:} bin $B$, arm set $\mathcal{I}$, confidence bound function $U$, source data $\mathcal{D}$.}
\State{Set $n_{k}^{P}(B;\mathcal{D}),\overline{Y}_{k}^{P}(B;\mathcal{D}),\tau_{k}^{\star}(B;\mathcal{D})$ as in (\ref{eq:n-k-B-Pdata}), (\ref{eq:Y-bar-k-B-Pdata}), (\ref{eq:tau-star}), respectively, $\forall k\in\mathcal{I}$.}


\State{Set $n_{k}^{P} \gets n_{k}^{P}(B;\mathcal{D})$, $\overline{Y}_{k} \gets \overline{Y}_{k}^{P}(B;\mathcal{D})$, and $\tau_{k}^{\star} \gets \tau_{k}^{\star}(B;\mathcal{D}), \forall k\in\mathcal{I}$.}
\State{Initialize $t\gets0$.}
\State{Initialize $\tau_{k} \gets 0, \forall k\in\mathcal{I}$.} 
    \Comment{initialize pull counts}
\State{Initialize $\underline{Y}^{\star}\gets\max\limits_{k\in\mathcal{I}}\big\{\overline{Y}_{k}-U_{k}(0,B;\mathcal{D})\big\}$.}
    \Comment{initialize largest reward lower bound}
\Loop
\If{$\tau_{k}\geq\tau_{k}^{\star}, \forall k\in\mathcal{I}$} 
	\Comment{condition to stop exploration}
\State{Set $t \gets t+1$.}
\State{Select arm $\widetilde{\pi}_{t}\gets\argmax\limits_{k\in\mathcal{I}}\overline{Y}_{k}$ (with ties broken arbitrarily) and receive reward $Y^{Q,({\widetilde{\pi}_{t}})}$.}
\State{Set $\tau_{\widetilde{\pi}_{t}}\gets\tau_{\widetilde{\pi}_{t}} + 1$.}
	\Comment{update pull count}
\State{Set $\tau_{t,k}\gets \tau_{k}, \forall k\in\mathcal{I}$, and $\mathcal{I}_{t}\gets\mathcal{I}$.}
	\Comment{record pull count and active arm set}
\State{Set $\overline{Y}_{\widetilde{\pi}_{t}}\gets\frac{1}{n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}}\big(Y^{Q,({\widetilde{\pi}_{t}})}+(n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}-1)\overline{Y}_{\widetilde{\pi}_{t}}\big)$.}
    \Comment{update estimated reward}
\Else
\For{$k\in\mathcal{I} \text{ such that } \tau_{k}<\tau_{k}^{\star}$}

    \Comment{only explore arms s.t.~pull counts less than upper bounds}
\If{$\overline{Y}_{k}+  U_{k}(\tau_{k},B;\mathcal{D}) \geq\underline{Y}^{\star}$}
    \Comment{eliminate arm s.t.~reward upper bound is smaller than largest reward lower bound}
\State{Set $t \gets t+1$.} 
\State{Select arm $\widetilde{\pi}_{t}\gets k$ and receive reward $Y^{Q,({\widetilde{\pi}_{t}})}$.}
\State{Set $\tau_{\widetilde{\pi}_{t}}\gets\tau_{\widetilde{\pi}_{t}} + 1$.}
	\Comment{update pull count}
\State{Set $\tau_{t,k}\gets \tau_{k}, \forall k\in\mathcal{I}$, and $\mathcal{I}_{t}\gets\mathcal{I}$.}
	\Comment{record pull count and active arm set}
\State{Set $\overline{Y}_{\widetilde{\pi}_{t}}\gets\frac{1}{n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}}\big(Y^{Q,({\widetilde{\pi}_{t}})}+(n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}-1)\overline{Y}_{\widetilde{\pi}_{t}}\big)$.}
    \Comment{update estimated reward}
\State{Set $\underline{Y}^{\star}\gets\max_{k\in\mathcal{I}}\big\{\overline{Y}_{k}-U_{k}(\tau_{k},B;\mathcal{D})\big\}$.}
    \Comment{update largest reward lower bound}

\Else \State{Eliminate arm $k$ from active arm set: $\mathcal{I} \gets\mathcal{I}\setminus\{k\}$.}
\EndIf

\EndFor
\EndIf
\EndLoop
\State{\textbf{Output:} policy $\{\widetilde{\pi}_{t}\}_{t\geq1}$, arm pull counts $\{(\tau_{t,k})_{k\in\mathcal{I}_t}\}_{t\geq1}$, sets of active arms $\{\mathcal{I}_{t}\}_{t\geq1}$.}
\end{algorithmic}

\caption{Transfer learning algorithm for contextual multi-armed bandits}
 \begin{algorithmic}[1]
\State{\textbf{Input:} arm set $\mathcal{I}$, horizon length
$n_{Q}$, smoothness parameters $\beta, C_{\beta}$, transfer parameters $\gamma$, exploration coefficient $\kappa$, $P$-data $\mathcal{D}^{P}$.}
\State{Initialize $\mathcal{L}_{1}\gets\{\mathcal{X}\}$, $\mathcal{I}(\mathcal{X})\gets\mathcal{I}$.} 
    \Comment{initialize partition and arm set}
\State{Initialize the policy $\widetilde{\pi}(\mathcal{X})$ by Procedure~\ref{alg:EA-TL}$\big(\mathcal{X},\mathcal{I}(\mathcal{X}),U,\mathcal{D}^{P} \big)$.}
\State{Initialize $N(\mathcal{X})\gets0$.}
    \Comment{initialize time for policy $\widetilde{\pi}(\mathcal{X})$}
\State{Initialize $\tau_{k}(\mathcal{X}) \gets 0$, and $\tau_{k}^{\star}(\mathcal{X};\mathcal{D}^{P}) $ as in \eqref{eq:tau-star}, $\forall k\in \mathcal{I}(\mathcal{X})$.} 
    \Comment{initialize rounds and set round upper bounds}
\For{$t=1,\dots,n_{Q}$}
\State{Draw a sample $X_{t}^{Q} \sim Q_{X}$.}
\State{Find the bin $B\in\mathcal{L}_{t}$ such that $X_{t}^{Q}\in B$.} 
\While{$|\mathcal{I}(B)|>1$

and $\tau_{k}(B)\geq\tau_{k}^{\star}(B;\mathcal{D}^{P}), \forall k\in\mathcal{I}(B)$}
    \Comment{keep partitioning $B$ until reaching suitable scale}
\If{$\tau_{k}^{\star}(B;\mathcal{D}^{P}) = 0, \forall k\in\mathcal{I}(B)$}
    \Comment{no exploration needed in $B$: discard suboptimal arms}
\State{Set $\underline{Y}^{\star}(B;\mathcal{D}^{P})\gets\max\limits_{k\in\mathcal{I}(B)}\big\{\overline{Y}_{k}^P(B;\mathcal{D}^{P})-  U_{k}(0,B;\mathcal{D}^{P}) \big\}$.}
    \Comment{set largest reward lower bound}
\State{Set $\mathcal{I}(B) \gets \big\{ k \in \mathcal{I}(B) : \overline{Y}_k^P(B;\mathcal{D}^{P})+U_{k}(0,B;\mathcal{D}^{P}) \geq \underline{Y}^{\star}(B;\mathcal{D}^{P}) \big\}$.}
    \Comment{update arm set}
\EndIf
\For{$B'\in\mathsf{child}(B)$}
\State{Set $\mathcal{I}(B')\gets\mathcal{I}(B)$.}
    \Comment{assign remaining arms in $B$ as initial arms in its children}
\State{Initialize the policy $\widetilde{\pi}(B')$ by Procedure~\ref{alg:EA-TL} $ \big(B',\mathcal{I}(B'),U,\mathcal{D}^{P} \big)$.}
\State{Set $N(B')\gets0$.}
    \Comment{initialize time for policy $\widetilde{\pi}(B')$}
\State{Set $\tau_{k}(B')\gets0$ and $\tau_{k}^{\star}(B';\mathcal{D}^{P})$ as in \eqref{eq:tau-star}, $\forall k\in\mathcal{I}(B')$.}
    \Comment{initialize rounds and set round upper bounds}
\EndFor
\State{Set $\mathcal{L}_{t}\gets (\mathcal{L}_{t}\setminus B)\cup\mathsf{child}(B)$.}
    \Comment{replace $B$ with its children in partition}
\State{Find the bin $B\in\mathcal{L}_{t}$ such that $ X_{t}^{Q}\in B$.}
\EndWhile
\State{Set $N(B)\gets N(B)+1$.}
    \Comment{update times $X_{t}^{Q} \in B$}
\State{Set $\pi_{t}\gets\widetilde{\pi}_{N(B)}(B)$.}
    \Comment{choose arm by policy $\widetilde{\pi}(B)$}
\State{Set $\mathcal{I}(B)\gets\widetilde{\mathcal{I}}_{N(B)} (B)$.}
    \Comment{update arm set by policy $\widetilde{\pi}(B)$}
\State{Set $\tau_{k}(B) \gets \widetilde{\tau}_{N(B),k}(B), \forall k\in\mathcal{I}(B)$.}
    \Comment{update numbers of rounds by policy $\widetilde{\pi}(B)$}
\EndFor
\State{\textbf{Output:} policy $\{\pi_{t}\}_{t\geq1}$.}
\end{algorithmic}

For any function $f(\cdot)$ on $\mathcal{X}$, bin $B$ in $\mathcal{X}$, and probability distribution $\lambda$ over $\mathcal{X}$, let $\Gamma_{B}f(\cdot ; \lambda)$ be the $L_{2}(\lambda)$-projection of $f$ onto the class of piecewise-constant functions over $B$, namely
\begin{align}
\label{eq:def-poly-proj}
\Gamma_{B}f(x ; \lambda) \defn \frac{1}{\lambda(B)} \int_{B} f(u)  \, \mathsf{d}\lambda(u)
\end{align}
if $\lambda(B) > 0$, and $\Gamma_{B}f(x ; \lambda) \defn 0$ otherwise.

Let $f:\mathcal{X} \rightarrow \mathbb{R}$ be a H\"{o}lder continuous function in $\mathcal{H}(\beta, C_\beta)$ with $0<\beta \leq 1$. For any probability distribution $\lambda$ and constants $l_{0}\geq 0$, $b >0$, we say $f$ is self-similar under $\lambda$ with parameters $l_{0}$ and $b$, if the following holds for any integer $l\geq l_{0}$:
\begin{align*}
\sup_{B\in\mathcal{B}_{l}}\sup_{x\in B}\big|\Gamma_{B}f(x ; \lambda)-f(x)\big|\geq b2^{-\beta l}.
\end{align*}

\caption{Smoothness estimation procedure}
 \begin{algorithmic}[1]

\State{\textbf{Input:} arm number $K$, horizon length $n_{Q}$, lower and upper bounds on smoothness $\underline{\beta}$ and $\overline{\beta}$, upper bound on transfer exponent $\overline{\gamma}$, $P$-data $\mathcal{D}^{P}$, tuning parameters $C_{1}, C_{2}$.}
\State{Set $n\gets n_{P}\vee n_{Q}$.}
\If{$n_{P}>n_{Q}$}
\State{Set $l_{1}\gets\Big\lceil\frac{\underline{\beta}\log_{2}(n)}{(d+2\overline{\beta}+\overline{\gamma})^2}\Big\rceil$, $l_{2}\gets l_{1}+\Big\lceil\frac{1}{d}\log_{2}(\log(n))\Big\rceil$, $l_{3}\gets\Big\lceil \frac{\overline{\beta}}{\underline{\beta}}l_{1}+\frac{1}{\underline{\beta}}\log_{2}(\log(n))\Big\rceil$.}
    \Comment{bandwidths of reward function estimators}
\State{Set $T\gets \Big\lceil C_{1} K n^{\frac{\underline{\beta}}{d+2\overline{\beta}}}\log^{\frac{d+\overline{\gamma}}{d}}(Kn)\Big\rceil$.}
    \Comment{sample size for smoothness estimation}
\State{Set $\mathcal{D}_{\mathsf{se}} \gets \Big\{\big(X_{i}^{P},\pi_{i}^{P},Y_{i}^{P,(\pi_{i}^{P})}\big)\Big\}_{i=1}^{T}$, $s_{P}\gets T+1$, $s_{Q}\gets1$.} 
    \Comment{samples for smoothness estimation}
\Else
\State{Set $l_{1}\gets\Big\lceil\frac{\underline{\beta}\log_{2}(n)}{(d+2\overline{\beta})^2}\Big\rceil$, $l_{2}\gets l_{1}+\Big\lceil\frac{1}{d}\log_{2}(\log(n))\Big\rceil$, $l_{3}\gets\Big\lceil \frac{\overline{\beta}}{\underline{\beta}}l_{1}+\frac{1}{\underline{\beta}}\log_{2}(\log(n))\Big\rceil$.}
    \Comment{bandwidths of reward function estimators}
\State{Set $T\gets \Big\lceil C_1 n^{\frac{\underline{\beta}}{d+2\overline{\beta}}}\log(Kn)\Big\rceil$.}
    \Comment{sample size for smoothness estimation}
\For{$t = 1,\dots, T$}
\State{Draw a sample $X_{t}^{Q}$, pull arm $\pi_{t}$ uniformly at random from $[K]$, and get the reward $Y_{t}^{Q,(\pi_{t})}$.}
\EndFor
\State{Set $\mathcal{D}_{\mathsf{se}} \gets \Big\{\big(X_{t}^{Q},\pi_{t},Y_{t}^{Q,(\pi_{t})}\big)\Big\}_{t=1}^{T}$, $s_{P}\gets1$, $s_{Q}\gets T+1$.}
    \Comment{samples for smoothness estimation}
\EndIf

\State Define the grid $\mathcal{M}$
\begin{align*}
\mathcal{M}\coloneqq\big\{x\in\mathcal{X}:x_{i}=(k_{i}-1/2)2^{-l_{3}},\,k_{i}=[2^{l_{3}}],i=[d]\big\}.
\end{align*}



\For{$i\in\{1,2\},k\in[K]$}
\State{Set $\mathcal{D}_{\mathsf{se}}^{(k)} \gets \{(X_{t},Y_{t}) : (X_{t},\pi_{t},Y_{t}) \in\mathcal{D}_{\mathsf{se}}\,\, \text{ such that }\,\, \pi_{t} = k \}$.}
\For{$x\in\mathcal{M}$}
\State{Find the bin $B_{i}(x)\in\mathcal{B}_{l_{i}}$ such that $x\in B_{i}(x)$.}
\State{Define the reward function estimator $\widehat{f}_{k}(x;2^{-l_{i}}) \defn \widehat{\eta}_{k}\big(x;B_{i}(x)\big)$, where
\begin{align}
\widehat{\eta}_{k}(x;B) \defn \frac{\sum_{(X_{t},Y_{t})\in\mathcal{D}_{\mathsf{se}}^{(k)}}Y_{t}\mathds{1}\{X_{t}\in B\}}
{1 \vee \sum_{(X_{t},Y_{t})\in\mathcal{D}_{\mathsf{se}}^{(k)}}\mathds{1}\{X_{t}\in B\}},\quad \forall B\in\mathcal{B}_{l_{i}}. 
\end{align}

}

\EndFor
\EndFor
\State {Set $\mathsf{b}\gets\max_{k\in[K]}\max_{x\in\mathcal{M}}\big|\widehat{f}_{k}(x;2^{-l_{1}})-\widehat{f}_{k}(x;2^{-l_{2}})\big|$.} 
\State {Set $\widehat{\beta}\gets-\frac{1}{l_{1}}\log(\mathsf{b})-C_{2}\frac{\log_{2}(\log (n))}{\log_{2}(n)}$.}
\State {\textbf{Output:} smoothness estimate $(\underline{\beta}\vee\widehat{\beta})\wedge\overline{\beta}$, time steps $s_{P}$ and $s_{Q}$, policy $\{\pi_{t}\}_{1\leq t<s_{Q}}$.}
\end{algorithmic}

Given a subset $\mathcal{D}$ of the source data $\mathcal{D}^{P}$ and the smoothness estimate $\widehat{\beta}$ returned by Procedure~\ref{alg:smoothness}, for any non-negative integer $\tau \geq 0$, bin $B$, and arm $k$, we define
\begin{align}
\widehat{U}_{k}(\tau,B;\mathcal{D})\coloneqq
\begin{cases}
2\sqrt{\frac{2}{\tau+n_{k}^{P}(B;\mathcal{D})}\log^{+}\big(\frac{n_{Q}|B|^{d}}{\tau}\big)} \vee 2\overline{C}_{\beta}|B|^{\widehat{\beta}}, & \text{if } \tau > 0, \\
2\sqrt{\frac{2}{n_{k}^{P}(B;\mathcal{D})}\log(n|B|^{d+2\widehat{\beta}})} \vee 2\overline{C}_{\beta}|B|^{\widehat{\beta}}, & \text{if } \tau = 0,
\end{cases}
 \label{eq:UCB-adapt}
\end{align}
where we recall the notations $\log^{+}(x)\defn\log(x)\vee1$, $n\defn n_{P}\vee n_{Q}$, and $1/0 = \infty$.

The associated non-negative upper bound on play rounds is defined by
\begin{align}
\widehat{\tau}^\star_k(B;\mathcal{D}) \defn \min_{\tau \in \{0\}\cup\mathbb{N}}\big\{ \tau : \widehat{U}_{k}(\tau,B;\mathcal{D}) \leq 2\overline{C}_{\beta}|B|^{\widehat{\beta}}\big\}. \label{eq:tau-star-adaptive}
\end{align}

\caption{Successive elimination procedure for a static bandit with source data}

\begin{algorithmic}[1]
\State{\textbf{Input:} bin $B$, arm set $\mathcal{I}$, confidence bound function $U$, source data $\mathcal{D}$.}
\State{Set $n_{k}^{P}(B;\mathcal{D}),\overline{Y}_{k}^{P}(B;\mathcal{D}),\tau_{k}^{\star}(B;\mathcal{D})$ as in (\ref{eq:n-k-B-Pdata}), (\ref{eq:Y-bar-k-B-Pdata}), (\ref{eq:tau-star}), respectively, $\forall k\in\mathcal{I}$.}


\State{Set $n_{k}^{P} \gets n_{k}^{P}(B;\mathcal{D})$, $\overline{Y}_{k} \gets \overline{Y}_{k}^{P}(B;\mathcal{D})$, and $\tau_{k}^{\star} \gets \tau_{k}^{\star}(B;\mathcal{D}), \forall k\in\mathcal{I}$.}
\State{Initialize $t\gets0$.}
\State{Initialize $\tau_{k} \gets 0, \forall k\in\mathcal{I}$.} 
    \Comment{initialize pull counts}
\State{Initialize $\underline{Y}^{\star}\gets\max\limits_{k\in\mathcal{I}}\big\{\overline{Y}_{k}-U_{k}(0,B;\mathcal{D})\big\}$.}
    \Comment{initialize largest reward lower bound}
\Loop
\If{$\tau_{k}\geq\tau_{k}^{\star}, \forall k\in\mathcal{I}$} 
	\Comment{condition to stop exploration}
\State{Set $t \gets t+1$.}
\State{Select arm $\widetilde{\pi}_{t}\gets\argmax\limits_{k\in\mathcal{I}}\overline{Y}_{k}$ (with ties broken arbitrarily) and receive reward $Y^{Q,({\widetilde{\pi}_{t}})}$.}
\State{Set $\tau_{\widetilde{\pi}_{t}}\gets\tau_{\widetilde{\pi}_{t}} + 1$.}
	\Comment{update pull count}
\State{Set $\tau_{t,k}\gets \tau_{k}, \forall k\in\mathcal{I}$, and $\mathcal{I}_{t}\gets\mathcal{I}$.}
	\Comment{record pull count and active arm set}
\State{Set $\overline{Y}_{\widetilde{\pi}_{t}}\gets\frac{1}{n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}}\big(Y^{Q,({\widetilde{\pi}_{t}})}+(n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}-1)\overline{Y}_{\widetilde{\pi}_{t}}\big)$.}
    \Comment{update estimated reward}
\Else
\For{$k\in\mathcal{I} \text{ such that } \tau_{k}<\tau_{k}^{\star}$}

    \Comment{only explore arms s.t.~pull counts less than upper bounds}
\If{$\overline{Y}_{k}+  U_{k}(\tau_{k},B;\mathcal{D}) \geq\underline{Y}^{\star}$}
    \Comment{eliminate arm s.t.~reward upper bound is smaller than largest reward lower bound}
\State{Set $t \gets t+1$.} 
\State{Select arm $\widetilde{\pi}_{t}\gets k$ and receive reward $Y^{Q,({\widetilde{\pi}_{t}})}$.}
\State{Set $\tau_{\widetilde{\pi}_{t}}\gets\tau_{\widetilde{\pi}_{t}} + 1$.}
	\Comment{update pull count}
\State{Set $\tau_{t,k}\gets \tau_{k}, \forall k\in\mathcal{I}$, and $\mathcal{I}_{t}\gets\mathcal{I}$.}
	\Comment{record pull count and active arm set}
\State{Set $\overline{Y}_{\widetilde{\pi}_{t}}\gets\frac{1}{n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}}\big(Y^{Q,({\widetilde{\pi}_{t}})}+(n_{\widetilde{\pi}_{t}}^{P}+\tau_{\widetilde{\pi}_{t}}-1)\overline{Y}_{\widetilde{\pi}_{t}}\big)$.}
    \Comment{update estimated reward}
\State{Set $\underline{Y}^{\star}\gets\max_{k\in\mathcal{I}}\big\{\overline{Y}_{k}-U_{k}(\tau_{k},B;\mathcal{D})\big\}$.}
    \Comment{update largest reward lower bound}

\Else \State{Eliminate arm $k$ from active arm set: $\mathcal{I} \gets\mathcal{I}\setminus\{k\}$.}
\EndIf

\EndFor
\EndIf
\EndLoop
\State{\textbf{Output:} policy $\{\widetilde{\pi}_{t}\}_{t\geq1}$, arm pull counts $\{(\tau_{t,k})_{k\in\mathcal{I}_t}\}_{t\geq1}$, sets of active arms $\{\mathcal{I}_{t}\}_{t\geq1}$.}
\end{algorithmic}

\caption{Adaptive transfer learning algorithm for contextual multi-armed bandits}

\begin{algorithmic}[1]
\State{\textbf{Input:} arm set $\mathcal{I}$, horizon length $n_{Q}$, lower and upper bounds on smoothness $\underline{\beta}$ and $\overline{\beta}$, upper bound on Lipschitz constant $\overline{C}_\beta$, upper bound on transfer exponent $\overline{\gamma}$, $P$-data $\mathcal{D}^{P}$.}

\State{Run Procedure~\ref{alg:smoothness} ($K, n_{Q}, \underline{\beta}, \overline{\beta}, \overline{\gamma}, \mathcal{D}^{P}$) to get the smoothness estimate $\widehat{\beta}$, time steps $s_{P}$ and $s_{Q}$, and policy $\{\pi_{t}^{\adp}\}_{1\leq t <s_{Q}}$.}

\State{Split the source data $\mathcal{D}^{P}_{\mathsf{dm}} \gets \Big\{ \big(X_{i}^{P},\pi_{i}^{P},Y^{P,(\pi_{i}^{P})} \big) \Big\}_{i=s_{P}}^{n_{P}}$ to aid in decision-making in the $Q$-bandit.}

\State{Set $\mathcal{L}_{s_{Q}}\gets\{\mathcal{X}\}$, and $\mathcal{I}(\mathcal{X})\gets\mathcal{I}$.}
    \Comment{initialize partition and arm set}
\State{Initialize the policy $\widetilde{\pi}(\mathcal{X})$ by Procedure~\ref{alg:EA-TL}
$\big(\mathcal{X}, \mathcal{I}(\mathcal{X}), \widehat{U}, \mathcal{D}^{P}_{\mathsf{dm}} \big)$.}
\State{Initialize $N(\mathcal{X})\gets0$.}
    \Comment{set time to $0$ for policy $\widetilde{\pi}(\mathcal{X})$}
\State{Initialize $\tau_{k}(\mathcal{X}) \gets 0$, and $\widehat{\tau}_{k}^{\star}(\mathcal{X};\mathcal{D}^{P}_{\mathsf{dm}})$ as in \eqref{eq:tau-star-adaptive}, $\forall k \in \mathcal{I}(\mathcal{X})$.}
    \Comment{initialize rounds and round upper bounds}
\For{$t=s_{Q},\dots,n_{Q}$}
    \State{Draw a sample $X_{t}^{Q} \sim Q_{X}$.}
    \State{Find the bin $B\in\mathcal{L}_{t}$ such that $X_{t}^{Q}\in B$.}
    \While{$|\mathcal{I}(B)|>1$ and $\tau_{k}(B)\geq\widehat{\tau}_{k}^{\star}(B;\mathcal{D}^{P}_{\mathsf{dm}}), \forall k\in\mathcal{I}(B)$}
        \Comment{keep partitioning $B$ until reaching suitable scale}
    \If{$\widehat{\tau}_{k}^{\star}(B;\mathcal{D}^{P}_{\mathsf{dm}}) = 0, \forall k\in\mathcal{I}(B)$}
        \Comment{no exploration needed in $B$: discard suboptimal arms}
    \State{Set $\underline{Y}^{\star}(B;\mathcal{D}^{P}_{\mathsf{dm}})\gets\max\limits_{k\in\mathcal{I}(B)}\big\{\overline{Y}_{k}^P(B;\mathcal{D}^{P}_{\mathsf{dm}})-\widehat{U}_{k}(0,B;\mathcal{D}^{P}_{\mathsf{dm}})\big\}$}
        \Comment{set largest reward lower bound}
    \State{Set $\mathcal{I}(B) \gets \{ k \in \mathcal{I}(B) : \overline{Y}_k^P(B;\mathcal{D}^{P}_{\mathsf{dm}}) + \widehat{U}_{k}(0,B;\mathcal{D}^{P}_{\mathsf{dm}}) \geq \underline{Y}^{\star}(B;\mathcal{D}^{P}_{\mathsf{dm}}) \}$.}
        \Comment{update arm set}
    \EndIf
    \For{$B'\in\mathsf{child}(B)$}
    \State{Set $\mathcal{I}(B')\gets\mathcal{I}(B)$.}
        \Comment{assign remaining arms in $B$ as initial arms in its children}
    \State{Initialize the policy $\widetilde{\pi}({B'})$ by Procedure~\ref{alg:EA-TL} $\big(B', \mathcal{I}(B'),\widehat{U},\mathcal{D}^{P}_{\mathsf{dm}} \big)$.}
    \State{Set $N(B')\gets0$.}
        \Comment{initialize time for policy $\widetilde{\pi}(B')$}
    \State{Set $\tau_{k}(B') \gets 0$, and  $\widehat{\tau}_{k}^{\star}(B';\mathcal{D}^{P}_{\mathsf{dm}}) $ as in \eqref{eq:tau-star-adaptive}, $\forall k\in\mathcal{I}(B')$.}
        \Comment{initialize rounds and round upper bounds}
\EndFor
\State{Set $\mathcal{L}_{t}\gets (\mathcal{L}_{t}\setminus B)\cup\mathsf{child}(B)$.}
    \Comment{replace $B$ with its children in partition}
\State{Find the bin $B\in\mathcal{L}_{t}$ such that $X_{t}^{Q}\in B$.}
\EndWhile
\State{Set $N(B)\gets N(B)+1$.}
    \Comment{update times $X_{t}^{Q} \in B$}
\State{Set $\pi^{\adp}_{t}\gets\widetilde{\pi}_{N(B)}(B)$.}
    \Comment{choose arm by policy $\widetilde{\pi}(B)$}
\State{Set $\mathcal{I}(B)\gets\widetilde{\mathcal{I}}_{N(B)} (B)$.}
    \Comment{update arm set by policy $\widetilde{\pi}(B)$}
\State{Set $\tau_{k}(B) \gets \widetilde{\tau}_{N(B),k}(B), \forall k\in\mathcal{I}(B)$.}
    \Comment{update numbers of rounds by policy $\widetilde{\pi}(B)$}
\EndFor
\State\textbf{Output:} policy $\pi^{\adp} = \{\pi^{\adp}_{t}\}_{t\geq1}$.

\end{algorithmic}
